pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        address user = address(0x1);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getTokens{value: 0}();
        c.NETM();
        address user2 = address(0x2);
        vm.deal(user2, 1 ether);
        vm.prank(user2);
        bool ok;
        try c.getTokens{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
